    public static function security__csp() {
        ?>
        <p>Cette page regroupe les spécifications des classes : <strong>security</strong> et <strong>csp</strong>.</p>
        <p>La classe security est entièrement automatisée dans le framework. Il n'est pas nécessaire de la modifier sauf cas particulier.</p>
        <p>La classe csp est un singleton, vous pouvez modifier les CSP via : csp::get_instance()</p>
        <p class="alert alert-warning">csp::get_instance()->apply() est appelé automatiquement par le framework, ne pas utiliser manuellement.</p>
        <p>Exemple :</p>
        <?php
        js::monaco_highlighter('<?php\n'
                . '// Désactive le mode "Report-Only" pour bloquer réellement les ressources interdites\n'
                . '// À utiliser dans le constructeur des pages une fois en production\n'
                . 'csp::get_instance()->set_report_only(false);\n'
                . '\n'
                . '// Autorise les scripts provenant du CDN jsDelivr\n'
                . 'csp::get_instance()->add_script_src("https://cdn.jsdelivr.net");\n'
                . '\n'
                . '// Autorise plusieurs domaines d\'images externes\n'
                . 'csp::get_instance()->add_img_src([\n'
                . '    "https://images.example.com",\n'
                . '    "https://cdn.example.com"\n'
                . ']);\n'
                . '\n'
                . '// Remplace complètement les endpoints AJAX autorisés\n'
                . 'csp::get_instance()->set_connect_src([\n'
                . '    "\'self\'",\n'
                . '    "https://api.example.com"\n'
                . ']);\n'
                . '\n'
                . '// Récupère les règles actuellement appliquées aux scripts\n'
                . '$scripts = csp::get_instance()->get_script_src();\n'
                . '\n'
                . '// Récupère l\'ensemble de la configuration CSP courante\n'
                . '$all = csp::get_instance()->get_all();\n'
                . '\n'
                . '// Ajoute un endpoint de reporting CSP personnalisé\n'
                . 'csp::get_instance()->add_report(\n'
                . '        "monitoring", // Nom du groupe CSP\n'
                . '        "https://monitoring.example.com/csp-report" // URL de reporting\n'
                . ');\n'
                . '\n'
                . '// Interdit complètement l\'utilisation des objets embarqués (<object>, <embed>, <applet>)\n'
                . 'csp::get_instance()->set_object_src("\'none\'");\n'
                . '\n'
                . '// Autorise l\'affichage du site uniquement depuis lui-même (anti-iframe externe)\n'
                . 'csp::get_instance()->set_frame_ancestors("\'self\'");\n'
                . '\n'
                . '// Autorise les formulaires vers un domaine externe de paiement\n'
                . 'csp::get_instance()->add_form_action("https://checkout.stripe.com");\n'
                . '\n'
                . '// Autorise les connexions WebSocket sécurisées\n'
                . 'csp::get_instance()->add_connect_src("wss://socket.example.com");\n'
                . '?>');
        ?>
        <hr>
        <p class="alert alert-danger">La politique CSP par défaut du framework implique que toutes les balises script doivent disposer du nonce généré pour la page courante afin de fonctionner.</p>
        <?php
        js::monaco_highlighter('<script nonce="<?=csp::get_nonce()?>">\n    // Votre code JS\n<\/script>\n');
        ?>
        <p>Si vous ne le faites pas, un message s'affichera pour vous avertir (uniquement en localhost). <br>
            Le code concerné s'affiche au survol de la souris. <br> Démonstration :</p>
        <p class="alert alert-warning" title="//votre code JS"><strong>Violation CSP : </strong>Script sans nonce !</p>
        <?php
    }

    public static function selectorDOM() {
        ?>
        <p>Source <a href="https://github.com/tj/php-selector">https://github.com/tj/php-selector</a> <br />
            "selectorDOM" permet de manipuler le DOM d'un document en PHP.
        </p>
        <div class="alert alert-danger" role="alert"><p>Attention à l'utilisation de cette classe sur des pages tiers.<br />
                La copie même partielle d'un site tiers sans autorisation préalable (et en dehors d'une utilisation strictement privée) est un délit.<br />
                (Article L.713-2 du Code de la propriété intellectuelle)</p></div>        

        <?php
        js::monaco_highlighter('<?php\n'
                . '//les selecteurs ont la même syntaxe que Jquery\n'
                . 'selectorDOM::select_elements("header", file_get_contents("http://{$_SERVER["HTTP_HOST"]}{$_SERVER["SCRIPT_NAME"]}?page=index"));\n'
                . '?>');
        ?><p>Résultat :</p><?php
        debug::print_r(json_decode('[{"name":"header","attributes":{"class":"page-header bg-info"},"text":"\r\n        DocumentationDocumentation de DWF\r\n      \r\n    ","children":[{"name":"h1","attributes":[],"text":"\r\n        DocumentationDocumentation de DWF\r\n      ","children":[{"name":"br","attributes":[],"text":"","children":[]},{"name":"small","attributes":[],"text":"Documentation de DWF","children":[]}]}]}]'));
    }

    public static function service() {
        ?>
        <p>
            La classe service est une classe qui permet de communiquer avec des services web d'un tiers ou que vous aurez vous même créé.
        </p>
        <?php
        js::monaco_highlighter('<?php\n'
                . '//envoie une requête GET à un service et en retourne la réponse \n'
                . 'service::HTTP_GET($url);\n\n'
                . '//envoie une requête POST à un service et en retourne la réponse\n'
                . 'service::HTTP_POST_REQUEST($url, $params, $ssl = false);\n\n'
                . '//envoie une requête POST à un service SANS en retourner la réponse\n'
                . 'service::HTTP_POST($url, $params, $ssl); //$ssl \n\n'
                . '//cette fonction est à utiliser pour filtrer les IP autorisées à acceder à votre script/service\n'
                . 'service::security_check($ip_allow=array("localhost", "127.0.0.1", "::1"));\n\n'
                . '//fonctions de conversion xml/csv -> json\n'
                . '$json=xml_to_json($xml_string);\n'
                . '$json=csv_to_json($csv_string);\n'
                . '?>');
    }

